<?php
require_once 'includes/config.php';require_admin();$id=(int)($_GET['id']??0);$q=$dbh->prepare('SELECT p.*,f.academic_year,f.term,f.amount_due,s.StudentName,s.RollId,c.ClassName,c.Section,a.transaction_id FROM student_fee_payments p JOIN student_term_fees f ON f.id=p.fee_id JOIN tblstudents s ON s.StudentId=f.student_id JOIN tblclasses c ON c.id=f.class_id LEFT JOIN fee_transaction_audit a ON a.receipt_reference=p.receipt_number WHERE p.id=:id');$q->execute([':id'=>$id]);$r=$q->fetch();if(!$r){http_response_code(404);exit('Receipt not found.');}if(!empty($r['transaction_id'])){$pdfPath=__DIR__.'/storage/fee-receipts/'.$r['transaction_id'].'.pdf';if(is_file($pdfPath)&&isset($_GET['pdf'])){header('Content-Type: application/pdf');header('Content-Disposition: inline; filename="'.preg_replace('/[^A-Za-z0-9._-]/','_',($r['receipt_number']?:'receipt')).'.pdf"');header('Content-Length: '.filesize($pdfPath));readfile($pdfPath);exit;}}$q=$dbh->prepare('SELECT COALESCE(SUM(amount),0) FROM student_fee_payments WHERE fee_id=:f');$q->execute([':f'=>$r['fee_id']]);$paid=(float)$q->fetchColumn();$balance=max(0,(float)$r['amount_due']-$paid);?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Fee Receipt <?=e($r['receipt_number'])?></title><style>body{font:15px Arial,sans-serif;color:#172033;margin:32px}.receipt{max-width:760px;margin:auto;border:1px solid #ccd2dc;padding:32px}.brand{text-align:center;border-bottom:2px solid #23395d;padding-bottom:18px}.brand h1{margin:0;color:#23395d}.row{display:flex;justify-content:space-between;padding:10px 0;border-bottom:1px solid #e5e7eb}.amount{font-size:22px;font-weight:bold}.muted{color:#64748b}.actions{max-width:760px;margin:12px auto}@media print{.actions{display:none}.receipt{border:0}}</style><link rel="stylesheet" href="css/srms-responsive.css" media="screen">
</head><body><div class="actions"><button onclick="window.print()">Print / Save as PDF</button> <?php if(!empty($r['transaction_id'])&&is_file(__DIR__.'/storage/fee-receipts/'.$r['transaction_id'].'.pdf')):?><a href="fee-payment-receipt.php?id=<?=$id?>&amp;pdf=1">Open generated PDF</a><?php else:?><span>PDF generation is queued; print/save as PDF is available now.</span><?php endif;?> <button onclick="window.close()">Close</button></div><article class="receipt"><header class="brand"><h1>School Fee Receipt</h1><p>Currency: Malawi Kwacha (MWK)</p><p class="muted">Student Result Management System</p></header><div class="row"><span>Receipt Reference</span><strong><?=e($r['receipt_number'])?></strong></div><div class="row"><span>Transaction ID</span><strong><?=e($r['transaction_id']??'Legacy transaction')?></strong></div><div class="row"><span>Payment Date</span><strong><?=e($r['payment_date'])?></strong></div><div class="row"><span>Student Name</span><strong><?=e($r['StudentName'])?></strong></div><div class="row"><span>Roll ID</span><strong><?=e($r['RollId'])?></strong></div><div class="row"><span>Class / Form</span><strong><?=e($r['ClassName'].' '.$r['Section'])?></strong></div><div class="row"><span>Academic Year</span><strong><?=e($r['academic_year'])?></strong></div><div class="row"><span>Term</span><strong><?=e($r['term'])?></strong></div><div class="row"><span>Payment Method</span><strong><?=e($r['payment_method'])?></strong></div><div class="row"><span>Amount Paid</span><strong class="amount">MWK <?=number_format((float)$r['amount'],2)?></strong></div><div class="row"><span>Remaining Balance</span><strong class="amount">MWK <?=number_format($balance,2)?></strong></div><p style="margin-top:36px">Received with thanks.</p><p class="muted">This receipt was generated from the SRMS transaction ledger.</p></article></body></html>
